{"code":"import json, math, re
from pathlib import Path

analysis_path = Path('/root/refill_analysis.json')
summary_path = Path('/root/refill_summary.md')
result = json.loads(analysis_path.read_text())

required_assumptions = {
    'patients_per_medication': 300,
    'fills_per_year_90_day': 4,
    'fills_per_year_100_day': 3,
    'tablets_per_fill_90_day': 90,
    'tablets_per_fill_100_day': 100,
    'switch_threshold_usd': 16000,
}
required_med_fields = {
    'medication', 'price_per_1000_tablets_usd', 'vial_size_drams', 'vial_price_usd',
    'reimbursement_per_fill_300_patients_usd', 'annual_drug_cost_90_day_usd',
    'annual_drug_cost_100_day_usd', 'annual_supply_cost_90_day_usd',
    'annual_supply_cost_100_day_usd', 'annual_reimbursement_90_day_usd',
    'annual_reimbursement_100_day_usd', 'annual_revenue_90_day_usd',
    'annual_revenue_100_day_usd', 'annual_revenue_difference_100_minus_90_usd'
}
required_totals = {
    'total_annual_revenue_90_day_usd', 'total_annual_revenue_100_day_usd',
    'total_annual_revenue_difference_100_minus_90_usd', 'absolute_total_revenue_difference_usd'
}
errors = []

if result.get('assumptions') != required_assumptions:
    errors.append(f"assumptions mismatch: {result.get('assumptions')}")
meds = result.get('medications')
if not isinstance(meds, list) or len(meds) != 10:
    errors.append('medications is not a list of 10 entries')
else:
    for idx, med in enumerate(meds):
        if set(med) != required_med_fields:
            errors.append(f"med {idx} field mismatch missing={sorted(required_med_fields-set(med))} extra={sorted(set(med)-required_med_fields)}")
        for k, v in med.items():
            if k.endswith('_usd') and isinstance(v, float) and not math.isclose(v, round(v, 2), abs_tol=1e-9):
                errors.append(f"{med.get('medication')} {k} not rounded to 2 decimals: {v}")
if set(result.get('totals', {})) != required_totals:
    errors.append('totals key mismatch')

total_diff = result['totals']['total_annual_revenue_difference_100_minus_90_usd']
abs_diff = result['totals']['absolute_total_revenue_difference_usd']
decision = result['recommendation']['decision']
expected_decision = 'switch_to_100_day' if abs(total_diff) < 16000 else 'keep_90_day'
if decision not in {'switch_to_100_day', 'keep_90_day'} or decision != expected_decision:
    errors.append(f"decision mismatch: got {decision}, expected {expected_decision}")

first = meds[0]
raw_vial_price = 0.008
expected_first = {
    'medication': 'Amlodipine 5mg',
    'price_per_1000_tablets_usd': 13.00,
    'vial_size_drams': 8,
    'vial_price_usd': round(raw_vial_price, 2),
    'reimbursement_per_fill_300_patients_usd': 2124.60,
    'annual_drug_cost_90_day_usd': round((90 * 4 * 300 / 1000) * 13.00, 2),
    'annual_drug_cost_100_day_usd': round((100 * 3 * 300 / 1000) * 13.00, 2),
    'annual_supply_cost_90_day_usd': round(raw_vial_price * 300 * 4, 2),
    'annual_supply_cost_100_day_usd': round(raw_vial_price * 300 * 3, 2),
    'annual_reimbursement_90_day_usd': round(2124.60 * 4, 2),
    'annual_reimbursement_100_day_usd': round(2124.60 * 3, 2),
}
expected_first['annual_revenue_90_day_usd'] = round(expected_first['annual_reimbursement_90_day_usd'] - expected_first['annual_drug_cost_90_day_usd'] - expected_first['annual_supply_cost_90_day_usd'], 2)
expected_first['annual_revenue_100_day_usd'] = round(expected_first['annual_reimbursement_100_day_usd'] - expected_first['annual_drug_cost_100_day_usd'] - expected_first['annual_supply_cost_100_day_usd'], 2)
expected_first['annual_revenue_difference_100_minus_90_usd'] = round(expected_first['annual_revenue_100_day_usd'] - expected_first['annual_revenue_90_day_usd'], 2)
for k, expected in expected_first.items():
    got = first.get(k)
    if isinstance(expected, float):
        if not math.isclose(got, expected, abs_tol=1e-9):
            errors.append(f"first med {k}: got {got}, expected {expected}")
    elif got != expected:
        errors.append(f"first med {k}: got {got}, expected {expected}")

sum_diffs = round(sum(m['annual_revenue_difference_100_minus_90_usd'] for m in meds), 2)
if not math.isclose(total_diff, sum_diffs, abs_tol=1e-9):
    errors.append(f"total diff {total_diff} != sum per-med diffs {sum_diffs}")
if not math.isclose(abs_diff, round(abs(total_diff), 2), abs_tol=1e-9):
    errors.append(f"abs diff {abs_diff} != abs(total_diff)")

summary = summary_path.read_text()
lines = summary.splitlines()
has_commas = bool(re.search(r'\d{1,3},\d{3}', summary))
if not (4 <= len(lines) <= 8):
    errors.append(f"summary line count {len(lines)} not 4-8")
for text in ['Total 90-day annual revenue', 'Total 100-day annual revenue', 'Absolute revenue difference', decision]:
    if text not in summary:
        errors.append(f"summary missing {text}")
if has_commas:
    errors.append('summary contains comma-separated number formatting')

if errors:
    print('VALIDATION FAILED')
    for e in errors:
        print('-', e)
    raise SystemExit(1)
print('VALIDATION PASSED')
print(f"assumptions keys: {sorted(result['assumptions'])}")
print(f"medications count: {len(meds)}")
print(f"spot-check first medication: {first['medication']} drug90={first['annual_drug_cost_90_day_usd']} supply90={first['annual_supply_cost_90_day_usd']} reimb90={first['annual_reimbursement_90_day_usd']} revenue90={first['annual_revenue_90_day_usd']} revenue100={first['annual_revenue_100_day_usd']} diff={first['annual_revenue_difference_100_minus_90_usd']}")
print(f"sum per-med diffs: {sum_diffs}")
print(f"total_diff: {total_diff}")
print(f"abs_diff: {abs_diff}")
print(f"decision: {decision}")
print(f"summary lines: {len(lines)}; comma separators: {'yes' if has_commas else 'no'}")"}
